#include "d64.h"
#include <stdlib.h>
#include <string.h>
unsigned rc_d64_track_sectors(unsigned track){return !track||track>42?0:track<=17?21:track<=24?19:track<=30?18:17;}
static unsigned index_of(const rc_d64 *d,unsigned t,unsigned s){if(!t||t>d->tracks||s>=rc_d64_track_sectors(t))return UINT32_MAX;unsigned n=s;for(unsigned i=1;i<t;++i)n+=rc_d64_track_sectors(i);return n;}
int rc_d64_open(rc_d64 *d,const uint8_t *data,size_t size,char *error,size_t cap){memset(d,0,sizeof *d);unsigned sectors=0;for(unsigned t=1;t<=42;++t){sectors+=rc_d64_track_sectors(t);if((t==35||t==40||t==42)&&(size==sectors*256u||size==sectors*257u)){d->tracks=t;d->sectors=sectors;break;}}if(!d->tracks)return rc_image_error(error,cap,"D64 size is not a 35, 40 or 42 track image");d->image=rc_media_from("",data,size);return d->image?1:rc_image_error(error,cap,"Out of memory");}
const uint8_t *rc_d64_sector(const rc_d64 *d,unsigned t,unsigned s){const unsigned i=index_of(d,t,s);return i==UINT32_MAX?NULL:d->image->data+i*256u;}
int rc_d64_write_sector(rc_d64 *d,unsigned t,unsigned s,const uint8_t bytes[256]){const unsigned i=index_of(d,t,s);if(i==UINT32_MAX||!d->image->writable)return 0;memcpy(d->image->data+i*256u,bytes,256);if(d->image->size>d->sectors*256u)d->image->data[d->sectors*256u+i]=1;d->image->dirty=1;return 1;}
uint8_t rc_d64_error(const rc_d64 *d,unsigned t,unsigned s){const unsigned i=index_of(d,t,s);return i==UINT32_MAX?0:d->image->size>d->sectors*256u?d->image->data[d->sectors*256u+i]:1;}
int rc_d64_create(rc_d64 *d,const uint8_t name[16],const uint8_t id[2],char *error,size_t cap){uint8_t *data=calloc(174848,1);if(!data)return rc_image_error(error,cap,"Out of memory");unsigned bam_index=17u*21u;uint8_t *bam=data+bam_index*256u;bam[0]=18;bam[1]=1;bam[2]=0x41;
    for(unsigned t=1;t<=35;++t){uint8_t *p=bam+4*t;p[0]=(uint8_t)rc_d64_track_sectors(t);for(unsigned s=0;s<rc_d64_track_sectors(t);++s)p[1+s/8]|=(uint8_t)(1u<<(s&7u));}bam[4*18]=17;bam[4*18+1]&=0xfcu;
    memset(bam+144,0xa0,27);if(name)memcpy(bam+144,name,16);if(id)memcpy(bam+162,id,2);bam[165]='2';bam[166]='A';data[(bam_index+1)*256u+1]=255;
    const int ok=rc_d64_open(d,data,174848,error,cap);free(data);if(ok)d->image->writable=1;return ok;}
void rc_d64_close(rc_d64 *d){rc_media_close(d->image);memset(d,0,sizeof *d);}
int rc_d64_directory(const rc_d64 *d,rc_d64_entry *entries,size_t capacity,size_t *count,char *error,size_t cap){uint8_t seen[802]={0};unsigned t=18,s=1;size_t n=0;while(t){const unsigned index=index_of(d,t,s);if(index==UINT32_MAX||seen[index])return rc_image_error(error,cap,"Invalid or cyclic D64 directory chain");seen[index]=1;const uint8_t *block=rc_d64_sector(d,t,s);for(unsigned i=0;i<8;++i){const uint8_t *p=block+i*32u;if(!(p[2]&15u))continue;if(n<capacity){rc_d64_entry *e=&entries[n];e->type=p[2];e->track=p[3];e->sector=p[4];memcpy(e->name,p+5,16);e->record_length=p[23];e->blocks=rc_image_u16(p+30);}++n;}t=block[0];s=block[1];}*count=n;return 1;}
int rc_d64_extract(const rc_d64 *d,const rc_d64_entry *entry,uint8_t **out,size_t *size,char *error,size_t cap){uint8_t seen[802]={0};uint8_t *data=malloc(d->sectors*254u);if(!data)return rc_image_error(error,cap,"Out of memory");unsigned t=entry->track,s=entry->sector;size_t n=0;while(t){const unsigned index=index_of(d,t,s);if(index==UINT32_MAX||seen[index]){free(data);return rc_image_error(error,cap,"Invalid or cyclic D64 file chain");}seen[index]=1;const uint8_t *p=rc_d64_sector(d,t,s);if(!p[0]&&!p[1]){free(data);return rc_image_error(error,cap,"Invalid final D64 sector length");}const size_t bytes=p[0]?254u:p[1]-1u;memcpy(data+n,p+2,bytes);n+=bytes;t=p[0];s=p[1];}*out=data;*size=n;return 1;}
void rc_d64_save(const rc_d64 *d,rc_state_writer *w){rc_sw_u32(w,1);rc_image_save(d->image,w);}
int rc_d64_load(rc_d64 *d,rc_state_reader *r){if(r->end-r->at<4||rc_sr_u32(r)!=1)return 0;rc_media *m=rc_image_load(r);if(!m)return 0;rc_d64 next;char error[128];if(!rc_d64_open(&next,m->data,m->size,error,sizeof error)){rc_media_close(m);return 0;}rc_media_close(next.image);next.image=m;rc_d64_close(d);*d=next;return 1;}
